const items = $input.all();
const tweets = items[0].json.data || [];

let totalLikes = 0, totalRetweets = 0, totalReplies = 0, totalImpressions = 0;

const formatted = tweets.map(tweet => {
  const m = tweet.public_metrics || {};
  totalLikes += m.like_count || 0;
  totalRetweets += m.retweet_count || 0;
  totalReplies += m.reply_count || 0;
  totalImpressions += m.impression_count || 0;

  return {
    tweet_id: tweet.id,
    text: tweet.text.substring(0, 100),
    created_at: tweet.created_at,
    likes: m.like_count || 0,
    retweets: m.retweet_count || 0,
    replies: m.reply_count || 0,
    impressions: m.impression_count || 0,
    engagement_rate: m.impression_count > 0 ? (((m.like_count + m.retweet_count + m.reply_count) / m.impression_count) * 100).toFixed(2) : '0'
  };
});

const summary = {
  week_ending: new Date().toISOString().split('T')[0],
  total_tweets: tweets.length,
  total_likes: totalLikes,
  total_retweets: totalRetweets,
  total_replies: totalReplies,
  total_impressions: totalImpressions,
  avg_engagement_rate: totalImpressions > 0 ? (((totalLikes + totalRetweets + totalReplies) / totalImpressions) * 100).toFixed(2) : '0',
  top_tweet: formatted.sort((a, b) => b.likes - a.likes)[0]?.text || 'N/A'
};

return [{json: {...summary, tweet_details: formatted}}];

